def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    for color in set(counts) - {background}:
        seen = set()
        for r in range(h):
            for c in range(w):
                if grid[r][c] != color or (r, c) in seen:
                    continue
                stack = [(r, c)]
                seen.add((r, c))
                cells = []
                while stack:
                    y, x = stack.pop()
                    cells.append((y, x))
                    for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                        if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == color and (yy,xx) not in seen:
                            seen.add((yy,xx))
                            stack.append((yy,xx))
                r0 = min(y for y, x in cells); r1 = max(y for y, x in cells)
                c0 = min(x for y, x in cells); c1 = max(x for y, x in cells)
                if r1-r0 < 2 or c1-c0 < 2:
                    continue
                perimeter = ({(r0,x) for x in range(c0,c1+1)} |
                             {(r1,x) for x in range(c0,c1+1)} |
                             {(y,c0) for y in range(r0,r1+1)} |
                             {(y,c1) for y in range(r0,r1+1)})
                if perimeter.issubset(set(cells)):
                    ih, iw = r1-r0-1, c1-c0-1
                    fill = 2 if ih % 2 == 0 and iw % 2 == 0 else 7
                    for y in range(r0+1, r1):
                        for x in range(c0+1, c1):
                            out[y][x] = fill
    return out

